//! Called from the code generated by the derive macro. Not public API: do not use directly; not
//! covered by semver guarantees.

use std::marker::PhantomData;
use std::str::FromStr;

use crate::BoxError;
use crate::parser::{self, ParseResult, Parser};
use crate::{FromEnvError, FromEnvErrors};

/// Selects the default parser for `T` with autoref-based specialization: the generated code calls
/// `(&&&Wrap::<T>::new()).__typenv_default_parser()`, and method resolution dereferences the
/// receiver until an impl applies:
///
/// 1. `&&&Wrap<T>` matches [`ViaFromStr`] on `&&Wrap<T>` if `T: FromStr`.
/// 2. `&&Wrap<T>` matches [`ViaTryFrom`] on `&Wrap<T>` if `T: TryFrom<String>`, which also covers
///    every `T: From<String>`.
/// 3. `&Wrap<T>` matches [`ViaFallback`] on `Wrap<T>` for every `T`. Its method requires
///    `T: NoDefaultParser`, which no type implements, so it never compiles. Because that bound is
///    on the method rather than the impl, it is only checked once the method has been selected,
///    which produces the custom error from [`NoDefaultParser`] instead of a generic "method not
///    found" error.
pub struct Wrap<T>(PhantomData<T>);

impl<T> Wrap<T> {
    pub const fn new() -> Self {
        Self(PhantomData)
    }
}

// Not derived: that would require `T: Default`.
impl<T> Default for Wrap<T> {
    fn default() -> Self {
        Self::new()
    }
}

pub trait ViaFromStr<T> {
    fn __typenv_default_parser(&self) -> fn(&str) -> ParseResult<T>;
}

impl<T> ViaFromStr<T> for &&Wrap<T>
where
    T: FromStr,
    T::Err: Into<BoxError>,
{
    fn __typenv_default_parser(&self) -> fn(&str) -> ParseResult<T> {
        parser::from_str::<T>
    }
}

pub trait ViaTryFrom<T> {
    fn __typenv_default_parser(&self) -> fn(&str) -> ParseResult<T>;
}

impl<T> ViaTryFrom<T> for &Wrap<T>
where
    T: TryFrom<String>,
    T::Error: Into<BoxError>,
{
    fn __typenv_default_parser(&self) -> fn(&str) -> ParseResult<T> {
        parser::try_into::<T>
    }
}

/// Never implemented. Only exists to produce a readable error for field types without a default
/// parser.
#[diagnostic::on_unimplemented(
    message = "`{Self}` cannot be parsed from an environment variable",
    label = "no default parser for `{Self}`",
    note = "implement `FromStr`, `TryFrom<String>` or `From<String>` for `{Self}`, or set a parser \
            with `#[env(parser = ...)]`"
)]
pub trait NoDefaultParser {}

pub trait ViaFallback<T> {
    fn __typenv_default_parser(&self) -> fn(&str) -> ParseResult<T>
    where
        T: NoDefaultParser;
}

impl<T> ViaFallback<T> for Wrap<T> {
    fn __typenv_default_parser(&self) -> fn(&str) -> ParseResult<T>
    where
        T: NoDefaultParser,
    {
        |_| Err("no default parser for this type".into())
    }
}

pub fn required<T>(path: &str, var: &str, parser: &impl Parser<T>) -> Result<T, FromEnvError> {
    match read(path, var)? {
        Some(value) => parse(path, var, value, parser),
        None => Err(FromEnvError::MissingVar {
            path: path.to_string(),
            var: var.to_string(),
        }),
    }
}

pub fn optional<T>(
    path: &str,
    var: &str,
    parser: &impl Parser<T>,
) -> Result<Option<T>, FromEnvError> {
    // No silent fallback to the None case if parsing fails
    read(path, var)?
        .map(|value| parse(path, var, value, parser))
        .transpose()
}

pub fn with_default<T>(
    path: &str,
    var: &str,
    default: &str,
    parser: &impl Parser<T>,
) -> Result<T, FromEnvError> {
    match read(path, var)? {
        Some(value) => parse(path, var, value, parser),
        None => parser
            .parse(default)
            .map_err(|error| FromEnvError::InvalidDefault {
                path: path.to_string(),
                var: var.to_string(),
                default: default.to_string(),
                source: error,
            }),
    }
}

/// Like [`with_default`], but the default is a typed value. It is only computed when the variable
/// is unset and is not passed through the parser.
pub fn with_default_value<T>(
    path: &str,
    var: &str,
    default: impl FnOnce() -> T,
    parser: &impl Parser<T>,
) -> Result<T, FromEnvError> {
    match read(path, var)? {
        Some(value) => parse(path, var, value, parser),
        None => Ok(default()),
    }
}

fn read(path: &str, var: &str) -> Result<Option<String>, FromEnvError> {
    match std::env::var(var) {
        Ok(value) => Ok(Some(value)),
        Err(std::env::VarError::NotPresent) => Ok(None),
        Err(ref error @ std::env::VarError::NotUnicode(ref malformed_value)) => {
            Err(FromEnvError::ParseError {
                path: path.to_string(),
                var: var.to_string(),
                value: malformed_value.to_string_lossy().to_string(),
                source: error.clone().into(),
            })
        }
    }
}

pub fn parse<T>(
    path: &str,
    var: &str,
    value: String,
    parser: &impl Parser<T>,
) -> Result<T, FromEnvError> {
    parser
        .parse(&value)
        .map_err(|error| FromEnvError::ParseError {
            path: path.to_string(),
            var: var.to_string(),
            value,
            source: error,
        })
}

#[derive(Default)]
pub struct ErrorCollector(Vec<FromEnvError>);

impl ErrorCollector {
    pub fn new() -> Self {
        Self(Vec::new())
    }

    pub fn handle<T>(&mut self, result: Result<T, FromEnvError>) -> Option<T> {
        match result {
            Ok(value) => Some(value),
            Err(error) => {
                self.0.push(error);
                None
            }
        }
    }

    pub fn handle_nested<T>(
        &mut self,
        prefix: &str,
        result: Result<T, FromEnvErrors>,
    ) -> Option<T> {
        match result {
            Ok(value) => Some(value),
            Err(FromEnvErrors(errors)) => {
                self.0.extend(errors.into_iter().map(|mut error| {
                    match &mut error {
                        FromEnvError::MissingVar { path, .. }
                        | FromEnvError::ParseError { path, .. }
                        | FromEnvError::InvalidDefault { path, .. } => {
                            *path = format!("{prefix}.{path}");
                        }
                    }
                    error
                }));
                None
            }
        }
    }

    pub fn finish(self) -> FromEnvErrors {
        FromEnvErrors(self.0)
    }
}

/// The total length of `parts`, used as the array length for [`concat`].
pub const fn concat_len(parts: &[&str]) -> usize {
    let mut len = 0;
    let mut i = 0;
    while i < parts.len() {
        len += parts[i].len();
        i += 1;
    }
    len
}

/// Concatenates `parts` at compile time. `N` must be [`concat_len`] of `parts`.
pub const fn concat<const N: usize>(parts: &[&str]) -> [u8; N] {
    let mut out = [0; N];
    let mut pos = 0;
    let mut i = 0;
    while i < parts.len() {
        let bytes = parts[i].as_bytes();
        let mut j = 0;
        while j < bytes.len() {
            out[pos] = bytes[j];
            pos += 1;
            j += 1;
        }
        i += 1;
    }
    assert!(pos == N, "`N` must be the total length of `parts`");
    out
}
